from pathlib import Path
import hashlib,json,datetime
R=Path(__file__).resolve().parents[1]
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
t=json.loads((R/'independent/final_results.json').read_text());assert t['passed']
for p,h in t['hashes'].items():assert sha(R/p)==h,p
l=json.loads((R/'R7_SAME_MINUTE_FINALIZATION.json').read_text());assert l['passed'] and l['durable_count']==1
assert [x['stage'] for x in l['observations']]==['first','update','finalized','duplicate','next_minute','disconnected']
paths=list((R/'src').glob('*.py'))+list((R/'dependencies/r3').glob('*.py'))+list((R/'native').glob('*'))+list((R/'artifacts').glob('*.dll'))+list((R/'tests').glob('*.py'))
report=dict(status='PASS_SCOPED_R7_ISOLATED_IMPLEMENTATION_REVIEW',overall='BLOCKED_GENUINE_SOURCE_AND_ACTUAL_AMIBROKER',reviewer='/root/forming_r2_review',utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),exact_hashes={str(p.relative_to(R)):sha(p) for p in paths if p.is_file()},independent_tests=t,author_tests_independently_rerun={'peer_checks':5,'pilot_cases':13,'resolver_cases':2},same_minute_evidence_reviewed=l,same_minute_author_suite_independently_rerun=False,closed_findings=['Second peer acquisition now appended incrementally; injected failure verifies first held process handle closed','Nested operation deadline preserves outer ingress budget and resets in finally; raw stream subscription included','Final exchange event duplicate ignores only local receipt timestamp; exchange-field changes rejected and original receipt preserved'],qualified_scope=['Windows exact reverse ESTABLISHED TCP tuple with held PID/creation/path/hash identity and precommit checks','Exact documented raw BTC path policy with test-owned TLS substitution only; zero REST, one URL stream and no reconnect','Owned localhost resolver child cancellation/reaping; OS limitations retained','Synthetic same-minute forming update, storage failure/retry, idempotent final, next minute and disconnected native readback'],remaining_blockers=['External Binance dispatch not implemented or authorized; local policy tests are not genuine endpoint acceptance','Peer table observation and process handle checks are not atomic with transaction commit','Sender and receiver share controller process in fixture; no production role authorization','Resolver subprocess reaping does not prove OS DNS infrastructure cancellation or hard real-time scheduling','Full-prefix historical admission unproven','Actual AmiBroker chart/refresh and weekly/mixed intervals not executed','Future pilot UTC window/process identities/writer authority and host lifecycle remain separately gated'],external_requests=0,protected_connections=0,production_mutations=0)
(R/'R7_INDEPENDENT_FINAL_REVIEW.json').write_text(json.dumps(report,indent=2));print(report['status'])
